namespace Domain;

public abstract class Entity { public Guid Id { get; set; } = Guid.NewGuid(); }

public class Usuario : Entity { public string Nome { get; set; } = ""; public string Email { get; set; } = ""; public string SenhaHash { get; set; } = ""; public PerfilUsuario Perfil { get; set; } public bool Ativo { get; set; } = true; public DateTime CriadoEm { get; set; } = DateTime.UtcNow; }
public class Instituicao : Entity { public string Nome { get; set; } = ""; public TipoInstituicao Tipo { get; set; } public string? CNES { get; set; } public string? CNPJ { get; set; } public string Endereco { get; set; } = ""; public string Municipio { get; set; } = ""; public string UF { get; set; } = ""; public decimal? Latitude { get; set; } public decimal? Longitude { get; set; } public bool Ativa { get; set; } = true; }
public class Doadora : Entity { public string Nome { get; set; } = ""; public string CPF { get; set; } = ""; public string? CNS { get; set; } public DateTime DataNascimento { get; set; } public string? Telefone { get; set; } public string? Email { get; set; } public string Endereco { get; set; } = ""; public decimal? Latitude { get; set; } public decimal? Longitude { get; set; } public DateTime? DataParto { get; set; } public string? TipoParto { get; set; } public StatusDoadora Status { get; set; } = StatusDoadora.PreCadastro; public DateTime CriadoEm { get; set; } = DateTime.UtcNow; }
public class TriagemDoadora : Entity { public Guid DoadoraId { get; set; } public bool TemHIV { get; set; } public bool TemHepatite { get; set; } public bool TemSifilis { get; set; } public bool UsaMedicamento { get; set; } public string? Medicamentos { get; set; } public bool Tabagista { get; set; } public bool UsaAlcool { get; set; } public bool UsaDrogas { get; set; } public bool TatuagemOuPiercingUltimos12Meses { get; set; } public bool Aprovada { get; set; } public string? Parecer { get; set; } public Guid ResponsavelId { get; set; } public DateTime CriadoEm { get; set; } = DateTime.UtcNow; }
public class ExameDoadora : Entity { public Guid DoadoraId { get; set; } public string TipoExame { get; set; } = ""; public DateTime DataExame { get; set; } public string Resultado { get; set; } = ""; public string? ArquivoUrl { get; set; } public bool Valido { get; set; } public DateTime CriadoEm { get; set; } = DateTime.UtcNow; }
public class RotaColeta : Entity { public string Nome { get; set; } = ""; public string? DiaSemana { get; set; } public string? Veiculo { get; set; } public string? Motorista { get; set; } public Guid ResponsavelId { get; set; } public StatusRota Status { get; set; } = StatusRota.Planejada; public DateTime? DataInicio { get; set; } public DateTime? DataFim { get; set; } }
public class CaixaTermica : Entity { public string Codigo { get; set; } = ""; public string? Descricao { get; set; } public decimal CapacidadeLitros { get; set; } public StatusCaixaTermica Status { get; set; } = StatusCaixaTermica.Disponivel; }
public class Coleta : Entity { public Guid DoadoraId { get; set; } public Guid RotaColetaId { get; set; } public Guid CaixaTermicaId { get; set; } public Guid ResponsavelId { get; set; } public DateTime? DataHoraInicio { get; set; } public DateTime? DataHoraFim { get; set; } public decimal? Latitude { get; set; } public decimal? Longitude { get; set; } public decimal? TemperaturaCaixaInicial { get; set; } public decimal? TemperaturaCaixaFinal { get; set; } public decimal? TemperaturaAmbiente { get; set; } public string? Observacoes { get; set; } public StatusColeta Status { get; set; } = StatusColeta.Agendada; }
public class Frasco : Entity { public string CodigoUnico { get; set; } = ""; public string? QrCode { get; set; } public Guid DoadoraId { get; set; } public Guid ColetaId { get; set; } public Guid CaixaTermicaId { get; set; } public Guid? LoteId { get; set; } public TipoLeite TipoLeite { get; set; } = TipoLeite.NaoClassificado; public decimal VolumeMl { get; set; } public StatusFrasco Status { get; set; } = StatusFrasco.Coletado; public DateTime? DataOrdenhaInicio { get; set; } public DateTime? DataOrdenhaFim { get; set; } public decimal? TemperaturaColeta { get; set; } public decimal? TemperaturaRecepcao { get; set; } public DateTime CriadoEm { get; set; } = DateTime.UtcNow; }
