public class ProcessamentoFrasco : Entity { public Guid LoteId { get; set; } public Guid FrascoOrigemId { get; set; } public Guid? FrascoDestinoId { get; set; } public TipoProcessamento TipoProcessamento { get; set; } public DateTime DataHora { get; set; } = DateTime.UtcNow; public Guid ResponsavelId { get; set; } public string? Observacoes { get; set; } }
public class ControleQualidade : Entity { public Guid FrascoId { get; set; } public Guid LoteId { get; set; } public decimal? AcidezDornic { get; set; } public decimal? Crematocrito { get; set; } public bool CorConforme { get; set; } public bool OdorConforme { get; set; } public bool SujidadeAusente { get; set; } public string? ResultadoMicrobiologico { get; set; } public bool Aprovado { get; set; } public Guid ResponsavelId { get; set; } public DateTime DataHora { get; set; } = DateTime.UtcNow; public string? Observacoes { get; set; } }
