public class Receptor : Entity { public string Nome { get; set; } = ""; public string? CNS { get; set; } public string Prontuario { get; set; } = ""; public DateTime DataNascimento { get; set; } public int? IdadeGestacional { get; set; } public decimal? PesoNascimento { get; set; } public string? Diagnostico { get; set; } public Guid HospitalId { get; set; } public string? Setor { get; set; } public string? Leito { get; set; } public StatusReceptor Status { get; set; } = StatusReceptor.Internado; }
