public class Auditoria : Entity { public Guid UsuarioId { get; set; } public string Acao { get; set; } = ""; public string Entidade { get; set; } = ""; public Guid EntidadeId { get; set; } public string? DadosAntes { get; set; } public string? DadosDepois { get; set; } public string? Ip { get; set; } public string? Dispositivo { get; set; } public decimal? Latitude { get; set; } public decimal? Longitude { get; set; } public DateTime CriadoEm { get; set; } = DateTime.UtcNow; }
